const diagnosticEvents=[];
function renderDiagnostics(){const list=$("diagnosticList");list.replaceChildren();$("diagnosticCount").textContent=diagnosticEvents.length+" events";$("diagnosticSummary").textContent=diagnosticEvents.length?("Latest: "+diagnosticEvents[diagnosticEvents.length-1].step+" \xB7 "+diagnosticEvents[diagnosticEvents.length-1].result):"No diagnostic events recorded yet.";for(const e of diagnosticEvents.slice(-30).reverse()){const row=node("div",new Date(e.at).toLocaleTimeString()+" \xB7 "+e.step+" \xB7 "+e.result+(e.detail?" \xB7 "+e.detail:""));row.className="asset";list.append(row)}}
async function recordDiagnostic(step,result,detail="",meta={}){const entry={at:new Date().toISOString(),step:String(step).slice(0,80),result:String(result).slice(0,40),detail:String(detail).slice(0,240),meta};diagnosticEvents.push(entry);if(diagnosticEvents.length>100)diagnosticEvents.shift();renderDiagnostics();try{await fetch("/api/auth/diagnostics",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify(entry),keepalive:true})}catch{}}
$("copyDiagnostics").addEventListener("click",async()=>{const report={generatedAt:new Date().toISOString(),userAgent:navigator.userAgent,online:navigator.onLine,events:diagnosticEvents};try{await navigator.clipboard.writeText(JSON.stringify(report,null,2));$("diagnosticSummary").textContent="Diagnostic report copied. Share it with support."; }catch{$("diagnosticSummary").textContent=JSON.stringify(report)}});
$("clearDiagnostics").addEventListener("click",()=>{diagnosticEvents.length=0;renderDiagnostics()});
function diagnosticEndpoint(path){return String(path).split("?")[0].replace(new RegExp("/[0-9a-f-]{36}(?=/|$)","gi"),"/:id").replace(new RegExp("/0x[0-9a-f]{40}(?=/|$)","gi"),"/:address").slice(0,120)}
async function api(path,options={}){const started=Date.now();try{const r=await fetch(path,{credentials:"same-origin",...options,headers:{"content-type":"application/json",...(options.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok){const message=d.error||"Request failed ("+r.status+")";if(path.startsWith("/api/owner/")&&path!=="/api/owner/diagnostics")void recordDiagnostic("owner.api","http_error",message,{endpoint:diagnosticEndpoint(path),httpStatus:r.status,durationMs:Date.now()-started});throw new Error(message)}if(path.startsWith("/api/owner/")&&path!=="/api/owner/diagnostics")void recordDiagnostic("owner.api","success","",{endpoint:diagnosticEndpoint(path),httpStatus:r.status,durationMs:Date.now()-started});return d}catch(error){if(path.startsWith("/api/owner/")&&path!=="/api/owner/diagnostics"&&!(error instanceof Error&&/Request failed/.test(error.message)))void recordDiagnostic("owner.api","network_error",error?.message||"Network request failed",{endpoint:diagnosticEndpoint(path),durationMs:Date.now()-started});throw error}}
