window.addEventListener("trustwallet#initialized",()=>{discoverLegacyProviders();updateConnectButton()});
function getTrustWalletInjectedProvider(){for(const item of discoveredProviders.values()){if((item.info?.rdns||"").toLowerCase()==="com.trustwallet.app"&&typeof item.provider?.request==="function")return item.provider}const tw=window.trustwallet;const direct=tw?.ethereum;if(direct&&typeof direct.request==="function")return direct;if(tw&&typeof tw.request==="function")return tw;const eth=window.ethereum;if(eth?.isTrust||eth?.isTrustWallet)return eth;if(Array.isArray(eth?.providers)){const match=eth.providers.find(p=>p?.isTrust||p?.isTrustWallet);if(match)return match}return null}
function discoverLegacyProviders(){try{const trust=getTrustWalletInjectedProvider();if(trust)addDiscoveredProvider({info:{name:"Trust Wallet",rdns:"com.trustwallet.app"},provider:trust})}catch{}try{const eth=window.ethereum;if(!eth)return;const list=Array.isArray(eth.providers)?eth.providers:[eth];for(const p of list){if(!p||typeof p.request!=="function")continue;let name="Browser wallet";if(p.isMetaMask)name="MetaMask";else if(p.isTrust||p.isTrustWallet)name="Trust Wallet";else if(p.isCoinbaseWallet)name="Coinbase Wallet";else if(p.isRabby)name="Rabby";else if(p.isBraveWallet)name="Brave Wallet";else if(p.isRainbow)name="Rainbow";addDiscoveredProvider({info:{name,rdns:name==="Trust Wallet"?"com.trustwallet.app":""},provider:p})}}catch{}}
