function walletBrand(name,rdns=""){const value=(name+" "+rdns).toLowerCase();if(value.includes("metamask"))return "metamask";if(value.includes("trust"))return "trustwallet";if(value.includes("coinbase"))return "coinbase";if(value.includes("base"))return "base";if(value.includes("rainbow"))return "rainbow";if(value.includes("rabby"))return "rabby";if(value.includes("brave"))return "brave";return "generic"}
function addWalletButton(root,name,detail,brand,onClick){const button=document.createElement("button");button.type="button";button.className="wallet-choice";button.setAttribute("aria-label",name+" \u2014 "+detail);const mark=document.createElement("span");mark.className="wallet-mark";mark.setAttribute("aria-hidden","true");mark.innerHTML=WALLET_LOGOS[brand]||WALLET_LOGOS.generic;const text=document.createElement("span");const strong=document.createElement("strong");strong.textContent=name;const small=document.createElement("small");small.textContent=detail;text.append(strong,small);button.append(mark,text);button.addEventListener("click",onClick);root.append(button)}
function addSectionLabel(root,label){const e=document.createElement("div");e.className="wallet-section-label";e.textContent=label;root.append(e)}
function renderWalletOptions(){const root=$("walletOptions");root.replaceChildren();const mobile=isMobileBrowser();const found=[...discoveredProviders.values()];if(found.length){addSectionLabel(root,"WALLETS DETECTED IN THIS BROWSER");for(const item of found)addWalletButton(root,item.info.name,"Connect in this browser",walletBrand(item.info.name,item.info.rdns),()=>connectWithProvider(item.provider,item.info.name))}
if(mobile){addSectionLabel(root,found.length?"WALLETS AVAILABLE IN THIS BROWSER":"CONNECT USING YOUR WALLET APP");for(const w of MOBILE_WALLETS){const detected=found.find(item=>walletBrand(item.info.name,item.info.rdns)===w.brand);addWalletButton(root,w.name,detected?"Connect in this wallet browser":(w.brand==="trustwallet"?"Connect securely with WalletConnect":w.detail),w.brand,async()=>{rememberWalletIntent(w.brand);walletIntent=w.brand;if(detected){await connectWithProvider(detected.provider,detected.info.name);return}if(w.brand==="trustwallet"){await connectWithWalletConnect("trustwallet");return}if(w.url){setStatus("walletModalStatus","Opening "+w.name+"\u2026");location.href=w.url();return}try{await navigator.clipboard.writeText(location.href);setStatus("walletModalStatus","Mainwell link copied. "+w.instruction)}catch{setStatus("walletModalStatus","Copy is unavailable in this browser. Copy the page address, then "+w.instruction,true)}})}const note=found.length?"A wallet provider is already available in this browser. Close this list and tap the main Connect button; Mainwell will connect directly.":(walletIntent?"You previously selected "+walletIntentName()+". Mainwell is waiting for that wallet's provider. Do not select the wallet again from this page. If it is not detected, retry connection; Mainwell will not reopen the same deep link.":"Open Mainwell inside your chosen wallet's DApp browser. Once the page loads there, tap the main Connect button. Mainwell will use that browser's injected wallet directly \u2014 you do not need to select the wallet again."); $("walletModalNote").textContent=note}else if(!found.length){addSectionLabel(root,"GET A WALLET");const links=[{name:"MetaMask",url:"https://metamask.io/download/",brand:"metamask"},{name:"Trust Wallet",url:"https://trustwallet.com/browser-extension",brand:"trustwallet"},{name:"Coinbase Wallet",url:"https://www.coinbase.com/wallet",brand:"coinbase"},{name:"Rabby Wallet",url:"https://rabby.io/",brand:"rabby"},{name:"Rainbow",url:"https://rainbow.me/",brand:"rainbow"}];for(const w of links)addWalletButton(root,w.name,"Visit official wallet site",w.brand,()=>window.open(w.url,"_blank","noopener,noreferrer"));$("walletModalNote").textContent="Install a wallet, refresh Mainwell, then select it here. Brave Wallet is also supported in the Brave browser."}else{$("walletModalNote").textContent="Choose your wallet. Mainwell requests account access and a one-time sign-in signature only."}
}
function openWalletModal(){
  const modal=$("walletModal");
  modal.classList.remove("hidden");
  setStatus("walletModalStatus","Opening wallet selection\u2026");
  try{discoverLegacyProviders()}catch(error){setStatus("walletModalStatus","Wallet detection is unavailable in this browser. You can still choose a wallet below.",true)}
  try{renderWalletOptions()}catch(error){setStatus("walletModalStatus","The wallet list could not be rendered. Please refresh and try again.",true)}
  try{window.dispatchEvent(new Event("eip6963:requestProvider"))}catch{}
  setTimeout(()=>{
    try{discoverLegacyProviders();renderWalletOptions();setStatus("walletModalStatus","Choose a wallet to continue.")}
    catch(error){setStatus("walletModalStatus","Wallet detection failed, but the selection window remains open.",true)}
  },350)
}
function closeWalletModal(){$("walletModal").classList.add("hidden");$("walletModal").setAttribute("aria-hidden","true")}
window.openWalletModal=openWalletModal;
window.closeWalletModal=closeWalletModal;
async function provider(){if(activeProvider)return activeProvider;discoverLegacyProviders();const first=discoveredProviders.values().next().value;if(first?.provider)return first.provider;throw new Error("No wallet is connected. Choose a wallet from the connection window.")}
async function connectWithProvider(p,name,lockHeld=false){if(!lockHeld){if(walletConnectionInFlight){setStatus("connectStatus","A wallet connection is already in progress. Resolve the current wallet prompt before trying again.",true);return}walletConnectionInFlight=true}const button=$("connect");button.disabled=true;closeWalletModal();activeProvider=p;const chosen=[...discoveredProviders.values()].find(x=>x.provider===p);if(chosen?.info?.rdns)sessionStorage.setItem("mainwell.selectedWalletRdns",chosen.info.rdns);if(chosen?.info?.name)sessionStorage.setItem("mainwell.selectedWalletName",chosen.info.name);attachProviderEvents(p);setStatus("connectStatus","Waiting for "+name+"\u2026");void recordDiagnostic("wallet.provider_request","started","",{wallet:name});try{const accounts=await p.request({method:"eth_requestAccounts"});account=accounts?.[0]||"";if(!/^0x[0-9a-fA-F]{40}$/.test(account))throw new Error("Wallet did not return a valid account.");chainId=Number(BigInt(await p.request({method:"eth_chainId"})));void recordDiagnostic("wallet.provider_approved","success","",{chainId,wallet:name});if(!NETWORKS[chainId])throw new Error("Unsupported network. Select one of the supported EVM networks.");void recordDiagnostic("auth.challenge","started","",{chainId});const challenge=await api("/api/auth/challenge",{method:"POST",body:JSON.stringify({address:account,chainId})});setStatus("connectStatus","Approve the sign-in message in your wallet. It does not authorize a transaction.");void recordDiagnostic("auth.personal_sign","awaiting_signature","",{chainId});const signature=await p.request({method:"personal_sign",params:[challenge.message,account]});void recordDiagnostic("auth.personal_sign","signature_returned","",{chainId});await api("/api/auth/verify",{method:"POST",body:JSON.stringify({address:account,chainId,nonce:challenge.nonce,signature})});void recordDiagnostic("auth.verify","success","",{chainId});location.assign("/")}catch(e){const message=String(e?.message||"Connection failed");const pending=Number(e?.code)===-32002||/already pending|request[^.]*pending/i.test(message);const shown=pending?"Your wallet already has a sign-in request pending. Open the wallet and resolve that existing request first. Approve it only if it clearly shows the Mainwell sign-in message (not a transaction), or reject it. Then tap Connect once. Mainwell will not retry automatically.":message;void recordDiagnostic("wallet.connect","failed",shown,{chainId:chainId||null,wallet:name});setStatus("connectStatus",shown,true)}finally{if(!lockHeld)walletConnectionInFlight=false;button.disabled=false}}
function getCurrentBrowserWallet(){
 const found=[...discoveredProviders.values()];
 const trust=found.find(item=>walletBrand(item.info.name,item.info.rdns)==="trustwallet");
 if(trust)return trust;
 return found.length===1?found[0]:null;
}
function updateConnectButton(){
 const button=$("connect"),current=getCurrentBrowserWallet();
 if(current){walletIntent=walletBrand(current.info.name,current.info.rdns);rememberWalletIntent(walletIntent);button.innerHTML="Connect "+current.info.name+' <span aria-hidden="true">\u2192</span>';button.setAttribute("aria-label","Connect "+current.info.name);button.dataset.detectedWallet="true";delete button.dataset.walletIntent}
 else if(walletIntent){const name=walletIntentName();button.innerHTML="Connect "+name+' <span aria-hidden="true">\u2192</span>';button.setAttribute("aria-label","Connect "+name);button.dataset.walletIntent=walletIntent;delete button.dataset.detectedWallet}
 else{button.innerHTML='Connect wallet <span aria-hidden="true">\u2192</span>';button.setAttribute("aria-label","Connect wallet");delete button.dataset.detectedWallet;delete button.dataset.walletIntent}
}
async function waitForInjectedWallet(timeoutMs=1800){
 const deadline=Date.now()+timeoutMs;
 try{window.dispatchEvent(new Event("eip6963:requestProvider"))}catch{}
 while(Date.now()<deadline){
  discoverLegacyProviders();
  const trust=getTrustWalletInjectedProvider();
  if(trust){addDiscoveredProvider({info:{name:"Trust Wallet",rdns:"com.trustwallet.app"},provider:trust});return {info:{name:"Trust Wallet",rdns:"com.trustwallet.app"},provider:trust}}
  const current=getCurrentBrowserWallet();
  if(current)return current;
  await new Promise(resolve=>setTimeout(resolve,100));
 }
 return null;
}
function connect(){
 const button=$("connect");
 try{
  discoverLegacyProviders();
  const current=getCurrentBrowserWallet();
  if(current){void connectWithProvider(current.provider,current.info.name);return}
  // Never deeplink from inside a wallet browser: that reopens the same page and
  // creates the Trust Wallet selection loop. Use one standard WalletConnect modal.
  void connectWithAppKit();
 }catch(error){
  button.disabled=false;
  setStatus("connectStatus",error instanceof Error?error.message:"Wallet connection could not start. Please try again.",true);
  void recordDiagnostic("wallet.connect","failed",error instanceof Error?error.message:"Wallet connection could not start");
 }
}
window.mainwellConnect=connect;
// Warm the wallet selector after the page has rendered, so the first tap does
// not have to download and initialize the three Reown modules on demand.
function warmAppKitOnIdle(){
 const warm=()=>{if(document.visibilityState==="visible")void getAppKitModal().catch(()=>{});};
 if("requestIdleCallback" in window)window.requestIdleCallback(warm,{timeout:1200});
 else window.setTimeout(warm,500);
}
if(document.readyState==="complete")warmAppKitOnIdle();
else window.addEventListener("load",warmAppKitOnIdle,{once:true});
