function formatUnits(raw,decimals){try{const n=BigInt(raw||"0"),d=10n**BigInt(decimals||0),whole=n/d,frac=(n%d).toString().padStart(Number(decimals||0),"0").replace(/0+$/,"");return whole.toString()+(frac?"."+frac:"")}catch{return "\u2014"}}
function renderPortfolio(){const root=$("portfolioGrid");root.replaceChildren();const entries=[];for(const w of wallets){for(const a of (w.assets||[])){entries.push({...a,network:w.network,wallet:w.address})}}$("portfolioCount").textContent=entries.length+" assets";if(!entries.length){const e=node("div","No asset balances have been returned yet. Mainwell automatically checks all seven supported EVM networks after connection. Use Refresh balances to retry any network that reports a monitoring issue.");e.className="portfolio-empty";root.append(e);return}for(const a of entries){const card=document.createElement("article");card.className="portfolio-card";const symbol=node("div",a.symbol||a.name||"Unknown asset");symbol.className="asset-symbol";const network=node("div",(NETWORKS[({ethereum:1,polygon:137,bsc:56,avalanche:43114,arbitrum:42161,optimism:10,base:8453})[a.network]]||a.network)+" \xB7 "+(String(a.assetId||"").includes(":native")?"Native asset":"ERC-20 token"));network.className="asset-network";const amount=node("div",formatUnits(a.amountRaw,a.decimals));amount.className="asset-amount";const meta=node("div",(a.name||"")+" \xB7 "+(a.tokenAddress?"Contract: "+a.tokenAddress:"Native coin")+(a.observedAt?" \xB7 Updated "+new Date(a.observedAt).toLocaleString():""));meta.className="asset-meta";card.append(symbol,network,amount,meta);root.append(card)}}
function renderWallets(){const root=$("wallets");root.replaceChildren();if(!wallets.length){const e=document.createElement("p");e.className="empty";e.textContent="No wallets registered for monitoring on this account yet.";root.append(e);renderPortfolio();return}for(const w of wallets){const item=document.createElement("article");item.className="wallet";const head=document.createElement("div");head.className="wallet-head";const addr=document.createElement("div");addr.className="address";addr.textContent=NETWORKS[w.chainId]||w.network;const tag=document.createElement("span");tag.className="tag";tag.textContent=w.status+(w.adminLocked?" \xB7 ADMIN LOCKED":" \xB7 AWAITING ADMIN LOCK");head.append(addr,tag);item.append(head);const a=document.createElement("p");a.className="address";a.textContent=w.address;item.append(a);for(const asset of (w.assets||[])){const line=document.createElement("div");line.className="asset";const name=document.createElement("span");name.textContent=asset.symbol||asset.name||asset.assetId;const qty=document.createElement("span");qty.textContent=asset.estimatedValueUsd?"$"+Number(asset.estimatedValueUsd).toFixed(2):"Balance observed";line.append(name,qty);item.append(line)}const actions=document.createElement("div");actions.className="actions";const refresh=document.createElement("button");refresh.className="secondary";refresh.textContent="Refresh assets";refresh.addEventListener("click",()=>refreshWallet(w.id));const toggle=document.createElement("button");toggle.className="secondary";toggle.textContent=w.status==="paused"?"Resume monitoring":"Pause monitoring";toggle.addEventListener("click",()=>toggleWallet(w));actions.append(refresh,toggle);item.append(actions);root.append(item)}renderPortfolio()}
